const slugOverrides:Record<string,string>={
  "women’s clothing":"womens-clothing",
  "women's clothing":"womens-clothing",
  "men’s clothing":"mens-clothing",
  "men's clothing":"mens-clothing",
};

export const slugify=(value:string)=>{
  const normalized=value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
  const override=slugOverrides[normalized];
  if(override) return override;
  return normalized.replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"");
};
export const fallbackNote="Through workshops, illustration systems and careful typographic choices, Hymn has built something that operates at human scale within technological infrastructure. The mascot guides without lecturing. The colours signal without shouting. The sub-brands distinguish themselves without fragmenting. In an industry that often designs for buildings first and people second, Shareman reverses the priority, a benevolent companion that happens to automate your laundry payments.";
type SeededRecommendation={productName:string; productHref:string; note:string};
const seededRecommendationsBySectionAndLabel:Map<string,readonly SeededRecommendation[]>=new Map<string,readonly SeededRecommendation[]>([
  ...homeRecommendations.map(item=>[`Home::${item.label}`,item.recommendations] as const),
  ...womenRecommendations.map(item=>[`Women’s Clothing::${item.label}`,item.recommendations] as const),
  ...menRecommendations.map(item=>[`Men’s Clothing::${item.label}`,item.recommendations] as const),
  ...kitchenRecommendations.map(item=>[`Kitchen::${item.label}`,item.recommendations] as const),
  ...gardenRecommendations.map(item=>[`Garden::${item.label}`,item.recommendations] as const),
  ...childrenRecommendations.map(item=>[`Children::${item.label}`,item.recommendations] as const),
  ...petsRecommendations.map(item=>[`Pets::${item.label}`,item.recommendations] as const),
  ...wellnessRecommendations.map(item=>[`Body::${item.label}`,item.recommendations] as const),
  ...sportRecommendations.map(item=>[`Sport::${item.label}`,item.recommendations] as const),
  ...officeRecommendations.map(item=>[`Office::${item.label}`,item.recommendations] as const),
  ...infrastructureRecommendations.map(item=>[`Infrastructure::${item.label}`,item.recommendations] as const),
]);

export const fallbackSections = seedSections.map(section=>{
  const sectionSlug=slugify(section.title);
  return {
    ...section,
    slug:sectionSlug,
    items:section.items.map(([label,productName],i)=>{
      const itemSlug=label==="Best Bath Towels"?"best-towels":slugify(label);
      const productSlug=slugify(productName);
      const seededRecommendations=seededRecommendationsBySectionAndLabel.get(`${section.title}::${label}`);
      return {
        label,
        productName,
        href:`/catalog/${sectionSlug}/${itemSlug}`,
        productHref:seededRecommendations?.[0]?.productHref||`https://example.com/products/${productSlug}`,
        updated:i===3,
        external:false,
        intro:seededRecommendations?.[0]?.note||fallbackNote,
        recommendations:seededRecommendations?.map((recommendation,index)=>({rank:index+1,...recommendation}))||[1,2,3].map(rank=>({rank,productName,productHref:`https://example.com/products/${productSlug}`,note:fallbackNote})),
      };
    }),
  };
});
